pug:
table.row.brad-full.white-bg
    tr
        td.wrapper.last.offset-by-one
            table.ten.columns
                tr
                    td.text-pad-small.pb44.pt44
                        p.data {{ text_1 }}
                        p.middle-title.pb16.pt16 {{ text_2 }}
                        .left-block.color-red
                            .padd
                                p.text.center {{ text_3 }}
                        .right-block.color-green
                            .padd
                                p.text.center {{ text_4 }}
                        .h-8 &nbsp;
                        .bottom-block.color-light-orange
                            p.text.center {{ text_5 }}

styl:
.brad-full { border-radius: 32px !important; }
.white-bg { background-color: #fff; }
.data { display: inline-block;
  padding: 6px 16px;
  background: #ffe6d5;
  border-radius: 12px;
  font-family: Helvetica !important;
  font-weight: 700;
  font-size: 16px;
  line-height: 20px;
  color: #ff8516;
  text-align: left; }
@media screen and (max-width: 600px) {
  .data { font-size: 14px !important; }
}
.middle-title { font-family: Helvetica !important;
  font-weight: 700;
  font-size: 32px;
  line-height: 42px;
  color: #393a44;
  vertical-align: middle; }
@media screen and (max-width: 600px) {
  .middle-title { font-size: 28px !important;
    line-height: 34px !important; }
}
.text { font-family: Helvetica !important;
  font-size: 18px;
  color: #393a44;
  letter-spacing: 0;
  line-height: 26px;
  font-weight: 400; }
.text.bold { font-weight: 700; }
.pb16 { padding-bottom: 16px; }
.pb44 { padding-bottom: 44px; }
.pt16 { padding-top: 16px; }
.pt44 { padding-top: 44px; }
.h-8 { font-size: 8px;
  line-height: 8px;
  height: 8px; }
.left-block { display: inline-block;
  width: 232px;
  border-radius: 24px;
  margin-right: 8px; }
@media screen and (max-width: 600px) {
  .left-block { display: block !important;
    margin: 0 auto 16px !important; }
}
.right-block { display: inline-block;
  width: 232px;
  border-radius: 24px; }
@media screen and (max-width: 600px) {
  .right-block { display: block !important;
    margin: 0 auto 16px !important; }
}
.bottom-block { padding: 37px 20px;
  border-radius: 24px; }
@media screen and (max-width: 600px) {
  .bottom-block { display: block !important;
    width: 228px !important;
    margin: 0 auto 16px !important;
    padding: 24px 40px !important; }
}
.color-red { background: #fdebeb; }
.color-green { background: #e7f6ee; }
.color-light-orange { background: #fcf5e7; }
.padd { padding: 24px 40px; }
